edits.marker:
		type: "text",
		text: `[dsh-bridge ${transport} message ${id} from ${message.from}]\n${text}`
	}],
	// 0.2.0 (session format v4): "plugin" is a retired source wrapper and native
	// admission refuses it ("format v4 message requires a producer-owned source
	// kind"). A third-party plugin's producer-owned kind is `plugin:<pkg name>`
	// (see @deepseek-ai/dsh-session-format-v3-to-v4's V3 rewrite fallback).
	source: {
		kind: `plugin:${name}`,
		form: transport
	}
}));

